'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const templateFields=[['initial','template','introduction'],['followup','followup_template','followup'],['yesPitch','yes_pitch_template','yesPitch'],['yesDemo','yes_demo_template','yesDemo']];
let live=false,gateway=location.origin,key='',busy=false,serverFeatures={},people=[],deliveries=[],leads=[],quotaResets=[],queuedSends=[],scheduledSends=[];
let accounts=[1,2,3].map(id=>({id,label:'Account '+id,authorized:false,api_configured:false,usage:{dm:{used:0,limit:15,remaining:15},group:{used:0,limit:30,remaining:30}}}));
let savedTemplate='',savedFollowupTemplate='',savedYesPitch='',savedYesDemo='',globalAutoYesEnabled=false,globalAutoFollowupEnabled=false,templateEditorsDirty=false,toastTimer,restoreAttempt;
const workspaceSession=WMMWorkspaceSession.create({getItem:n=>localStorage.getItem(n),setItem:(n,v)=>localStorage.setItem(n,v),removeItem:n=>localStorage.removeItem(n)},{getItem:n=>sessionStorage.getItem(n),setItem:(n,v)=>sessionStorage.setItem(n,v),removeItem:n=>sessionStorage.removeItem(n)});
let workspaceActionErrors=[];function recordWorkspaceError(error,button){workspaceActionErrors.unshift({title:button?.textContent?.trim()||'Request error',message:error.message||'Request failed',path:error.requestPath||'',status:error.status||null});workspaceActionErrors=workspaceActionErrors.slice(0,10);if(live)renderPendingQueue()}
const slot=()=>Number($('#loginAccount').value)||1;
const uniqueRequest=()=>crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',7000)}
async function action(button,fn){if(busy)return;busy=true;const prior=button?.disabled;if(button)button.disabled=true;try{return await fn()}catch(error){toast(error.message);recordWorkspaceError(error,button);console.error('Workspace action failed:',error.message)}finally{busy=false;if(button)button.disabled=!!prior}}
function view(page,historyMode='push'){page=['safety','groups','pending','sent','replies','templates','connections'].includes(page)?page:'groups';$$('.content>.section').forEach(n=>n.classList.toggle('active',n.id===page));$$('nav [data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===page));$('#breadcrumb').textContent=({safety:'Outreach controls',groups:'TG Groups admins',pending:'Pending Messages',sent:'Sent Messages',replies:'Replies',templates:'Message templates',connections:'Settings'})[page];workspaceSession.page(page);document.title=({safety:'Outreach controls',pending:'Pending Messages',sent:'Sent Messages',replies:'Replies',groups:'TG Groups admins',templates:'Message templates',connections:'Settings'})[page]+' · WMM Team';const path=WMMPageRoutes.paths[page];if(location.pathname!==path)history[historyMode==='replace'?'replaceState':'pushState']({page},'',path);window.scrollTo({top:0,behavior:'instant'})}
function expireWorkspaceSession(){workspaceSession.clear();key='';live=false;tgAdminSelected.clear();tgAdminBatchPlan=null;conversationDraft=null;$('#conversationComposer')?.close();closeTgAdminComposer();clearTelegramQr();$('#workspaceRestore').hidden=true;$('#appShell').hidden=true;$('#loginScreen').hidden=false;$('#dashboardLoginError').textContent='Your session expired. Sign in to reload your records.'}
async function rawApi(path,body){if(!key)throw Error('Sign in to this workspace first.');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);try{const response=await fetch(gateway+path,{method:body===undefined?'GET':'POST',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json','X-Workspace-Expires-At':workspaceSession.read()?.expiresAt||''},body:body===undefined?undefined:JSON.stringify(body),signal:controller.signal});if(response.status===401){expireWorkspaceSession();throw Error('Your workspace session expired. Sign in again.')}const data=await response.json();if(!response.ok){const error=Error(typeof data.detail==='string'?data.detail:data.detail?.message||'Request failed');error.status=response.status;error.code=data.detail?.code;throw error}if(path==='/status'){$('#workspaceApiAlert').hidden=true;$('#workspaceApiAlert').textContent=''}return data}catch(error){error.requestPath=path;if(path==='/status'){const message=error.name==='AbortError'?'Server connection timed out. The displayed queue may be out of date. Refresh to check again.':error.message;$('#workspaceApiAlert').textContent='Connection error: '+message;$('#workspaceApiAlert').hidden=false}throw error}finally{clearTimeout(timer)}}
const api=(path,body)=>rawApi(path,body);
function exchangeOptions(){return '<option value="">Choose exchange…</option>'+Object.entries(WMMMessageModel.exchanges).map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('')}
function validateMessageToken(text,value){const symbol=WMMMessageModel.normalizeToken(value);if(symbol&&!/^[A-Za-z0-9._-]{1,32}$/.test(symbol))throw Error('Enter a token symbol of up to 32 letters, numbers, dots, underscores or hyphens.');if(WMMMessageModel.requiresToken(text)&&!symbol)throw Error('Enter the token above the preview.');return symbol}
function renderLogin(){const a=accounts.find(a=>a.id===slot());if(!a)return;const step=a.login_step||'phone';$('#telegramPasswordStep').hidden=step!=='password';$('#telegramCodeStep').hidden=step==='password';$('#verify').textContent=step==='password'?'Verify password & connect':'Verify code & connect';$('#telegramState').textContent='Account '+a.id+' · '+(a.authorized?'Connected':'Not connected');$('#apiState').textContent=a.api_configured?'API credentials saved for this account.':'Save the matching API ID and Hash first.';$('#telegramLoginHelp').textContent=a.authorized?'This account is connected.':step==='password'?'Code accepted. Enter your Telegram two-step password.':step==='qr'?'Scan the QR with your signed-in Telegram phone.':step==='code'?'A code is pending'+(a.login_phone_hint?' for '+a.login_phone_hint:'')+'. Check the delivery details below.':'Use QR login or request a code, then verify it.';$('#settingsAccountSummary').textContent=a.error||a.health?.last_error||'';$('#logout').disabled=!a.authorized;$('#saveApi').disabled=a.authorized;$('#requestCode').disabled=a.authorized||!a.api_configured;$('#startQrLogin').disabled=a.authorized||!a.api_configured;$('#verify').disabled=a.authorized}
function clearLogin(){for(const id of ['phone','loginCode','password','apiId','apiHash'])$('#'+id).value=''}
function loadTemplateEditors(){loadVariantEditors();$('#globalAutoReplies').checked=globalAutoYesEnabled;$('#globalAutoFollowup').checked=globalAutoFollowupEnabled;if(!$('#templatePreviewExchange').options.length)$('#templatePreviewExchange').innerHTML=exchangeOptions();$('#templatesGatewayHint').textContent='Use every distinct saved option before repeating. Review each message before queueing.';updateTemplatePreviews()}
function updateTemplatePreviews(){const p={name:'Recipient',username:'username'};for(const [id] of templateFields)$('#'+id+'TemplatePreview').textContent=WMMMessageModel.personalize($('#'+id+'TemplateEditor').value,p,$('#templatePreviewToken').value,$('#templatePreviewExchange').value)}
function dirtyTemplates(){templateEditorsDirty=true;$('#templatesSaveState').textContent='Unsaved changes. Save to use these options.';updateTemplatePreviews()}
async function saveAllTemplates(){const variants=readVariantDrafts(),body={template_variants:variants,auto_yes_enabled:$('#globalAutoReplies').checked,auto_followup_enabled:$('#globalAutoFollowup').checked};for(const [,key] of templateFields)body[key]=variants[key].find(Boolean);await rawApi('/templates',body);templateEditorsDirty=false;await refresh(false);$('#templatesSaveState').textContent='All four message types and their five-option pools saved.';toast('Message templates saved.')}
function renderQueue(){const rows=queuedSends.filter(q=>['Queued','Sending','Needs attention'].includes(q.status));$('#queueRecords').innerHTML=rows.length?rows.map(q=>`<article class="queue-item"><b>${esc(q.name||q.target)}</b> · Account ${esc(q.account_id)} · ${esc(q.status)}<p class="hint">${q.status==='Queued'?'Not before '+esc(new Date(q.next_attempt_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',hour12:true,timeZoneName:'short'})):esc(q.error||'Sending now')}</p><details><summary>Message preview</summary><div class="messagecopy">${esc(q.message)}</div></details>${q.status==='Queued'?`<button data-cancel-queue="${esc(q.queue_id)}">Cancel this message</button>`:''}</article>`).join(''):'<p class="hint">No messages waiting to send.</p>';$$('[data-cancel-queue]').forEach(b=>b.onclick=()=>action(b,async()=>{await rawApi('/send-queue/cancel',{id:b.dataset.cancelQueue});await refresh(false);toast('Queued message cancelled.')}))}
async function refresh(loadSettings=true){const data=await rawApi('/status');if(!data.accounts||!data.features?.admin_bulk_sends)throw Error('This server needs the included WMM backend.');accounts=data.accounts;serverFeatures=data.features;people=(data.contacts||[]).filter(p=>!p.is_bot);deliveries=data.deliveries||[];leads=data.leads||[];quotaResets=data.quota_resets||[];queuedSends=data.queued_sends||[];scheduledSends=data.scheduled_sends||[];groupAdminSnapshots=data.group_admins||[];window.renderOutreachSafety?.(data);const cfg=data.settings||{};savedTemplate=cfg.template||'';savedFollowupTemplate=cfg.followup_template||'';savedYesPitch=cfg.yes_pitch_template||'';savedYesDemo=cfg.yes_demo_template||'';globalAutoYesEnabled=cfg.auto_yes_enabled!==false;globalAutoFollowupEnabled=cfg.auto_followup_enabled!==false;hydrateTemplateVariants(cfg);live=true;applyAccountSetup(data);if(!templateEditorsDirty)loadTemplateEditors();if(loadSettings){$('#composeToken').value=cfg.token_symbol||'';$('#templatePreviewToken').value=cfg.token_symbol||''}renderLogin();renderGroupAdmins();renderQueue();renderConversations();pendingLastSync=Date.now();renderPendingQueue();updateTemplatePreviews();$('#connectionBadge').textContent=visibleAccounts().filter(a=>a.authorized).length+'/'+visibleAccounts().length+' accounts connected'}
async function restoreWorkspace(){if(restoreAttempt)return restoreAttempt;const saved=workspaceSession.read();if(!saved)return;key=saved.token;gateway=location.origin;if(saved.gateway!==gateway){workspaceSession.clear();key='';return}$('#loginScreen').hidden=true;$('#appShell').hidden=true;$('#workspaceRestore').hidden=false;$('#retryWorkspaceRestore').disabled=true;restoreAttempt=(async()=>{try{await refresh();if(!key||!workspaceSession.read())return;const renewed=await rawApi('/auth/session',{});workspaceSession.save({...saved,token:renewed.access_token,expiresAt:renewed.expires_at});key=renewed.access_token;$('#workspaceRestore').hidden=true;$('#appShell').hidden=false;view(WMMPageRoutes.resolve(location.pathname,saved.page),'replace')}catch(error){if(key)$('#workspaceRestoreStatus').textContent='Your server may be waking up or temporarily offline. Your session is kept. Retry to load your saved data.'}finally{$('#retryWorkspaceRestore').disabled=false;restoreAttempt=null}})();return restoreAttempt}
if(workspaceSession.read()){$('#loginScreen').hidden=true;$('#workspaceRestore').hidden=false}
document.addEventListener('DOMContentLoaded',()=>{
 $$('nav [data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));window.addEventListener('popstate',()=>view(WMMPageRoutes.resolve(location.pathname),'replace'));
 $('#dashboardLoginForm').onsubmit=e=>{e.preventDefault();return action($('#dashboardLoginButton'),async()=>{let response,data;try{response=await fetch('/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:$('#dashboardUsername').value.trim(),password:$('#dashboardPassword').value})});data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Sign-in failed.')}catch(error){$('#dashboardLoginError').textContent=error.message;throw error}finally{$('#dashboardPassword').value=''}key=data.access_token;const stored=workspaceSession.save({gateway:location.origin,token:key,expiresAt:data.expires_at,page:WMMPageRoutes.resolve(location.pathname)});$('#loginScreen').hidden=true;$('#appShell').hidden=false;try{await refresh();view(WMMPageRoutes.resolve(location.pathname),'replace');if(!stored)toast('Signed in. Browser storage is blocked, so refresh will require sign-in.')}catch(error){$('#appShell').hidden=true;$('#workspaceRestore').hidden=false;$('#workspaceRestoreStatus').textContent='Signed in, but records could not be loaded. Retry the connection.';throw error}})};
 $('#dashboardLogout').onclick=()=>action($('#dashboardLogout'),async()=>{try{await rawApi('/auth/logout',{})}finally{workspaceSession.clear();location.reload()}});
 $('#retryWorkspaceRestore').onclick=()=>action($('#retryWorkspaceRestore'),restoreWorkspace);
 $('#cancelWorkspaceRestore').onclick=()=>{expireWorkspaceSession();$('#dashboardLoginError').textContent=''};
 $('#loginAccount').onchange=()=>{clearLogin();clearTelegramQr();renderLogin();renderTelegramCodeRecovery()};
 $('#saveApi').onclick=()=>action($('#saveApi'),async()=>{const id=Number($('#apiId').value),hash=$('#apiHash').value.trim();if(!Number.isSafeInteger(id)||id<=0||!/^[a-fA-F0-9]{32}$/.test(hash))throw Error('Enter a numeric API ID and matching 32-character API Hash.');try{await rawApi('/telegram-api',{account_id:slot(),api_id:id,api_hash:hash})}finally{$('#apiHash').value=''}await refresh(false);toast('Telegram API saved.')});
 $('#requestCode').onclick=()=>action($('#requestCode'),async()=>{const phone=$('#phone').value.trim();if(!phone)throw Error('Enter your phone number with + and country code.');const result=await rawApi('/login',{account_id:slot(),phone});await refresh(false);toast(result.authorized?'Account is already connected.':result.existing_code?'Your code is still pending. Check delivery guidance or use QR login.':'Code requested. Check '+(result.code_delivery||'Telegram’s delivery method')+'.')});
 $('#verify').onclick=()=>action($('#verify'),async()=>{let result;try{result=await rawApi('/verify',{account_id:slot(),phone:$('#phone').value.trim(),code:$('#loginCode').value.trim(),password:$('#password').value})}finally{$('#password').value=''}if(result.password_required){$('#loginCode').value='';await refresh(false);toast('Code accepted. Enter your two-step password.');return}clearLogin();await refresh(false);toast('Telegram account connected.')});
 $('#logout').onclick=()=>action($('#logout'),async()=>{await rawApi('/logout',{account_id:slot()});clearLogin();clearTelegramQr();await refresh(false);toast('Telegram account disconnected. Records retained.')});
 for(const [id,,fallback] of templateFields){$('#'+id+'TemplateEditor').oninput=()=>{updateVariantDraft(id);dirtyTemplates()};$('#reset'+id[0].toUpperCase()+id.slice(1)+'Template').onclick=()=>{$('#'+id+'TemplateEditor').value=WMMMessageModel[fallback];updateVariantDraft(id);dirtyTemplates()}}
 $('#templatePreviewToken').oninput=updateTemplatePreviews;$('#templatePreviewExchange').onchange=updateTemplatePreviews;$('#globalAutoReplies').onchange=dirtyTemplates;$('#globalAutoFollowup').onchange=dirtyTemplates;$('#saveTemplates').onclick=()=>action($('#saveTemplates'),saveAllTemplates);$('#saveTemplatesBottom').onclick=()=>action($('#saveTemplatesBottom'),saveAllTemplates);
 $('#refreshQueue').onclick=()=>action($('#refreshQueue'),()=>refresh(false));
 view(WMMPageRoutes.resolve(location.pathname,workspaceSession.read()?.page||'groups'),'replace');void restoreWorkspace();
 setInterval(async()=>{if(!live||!key||busy||(document.activeElement?.matches('input,textarea,select')&&!$('#pending').classList.contains('active')))return;try{await refresh(false)}catch{}},10000);
 setInterval(()=>{if(live&&document.visibilityState==='visible')fetch('/api/health',{cache:'no-store'}).catch(()=>{})},600000);
 window.addEventListener('online',()=>{if(!live&&workspaceSession.read())void restoreWorkspace()});
});
